DECLARE @NUM_WEEK NVARCHAR(8);
DECLARE @RTYPE_DESC NVARCHAR(MAX);
--MAX보다 작은 제일 큰값에 + 1 한 값을 저장한다.
--MAX 구한다.
SELECT TOP 1 @RTYPE_NUM_MAX = RTYPE_NUM FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE MODULE= @MODULE AND ROLLIN= @ROLLIN ORDER BY RTYPE_NUM DESC;
--상기 MAX 보다 작은 MAX 구한다.
SELECT TOP 1 @RTYPE_NUM_MIN = RTYPE_NUM FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE RTYPE_NUM < @RTYPE_NUM_MAX AND MODULE= @MODULE AND ROLLIN= @ROLLIN ORDER BY RTYPE_NUM DESC;
PRINT '@RTYPE_NUM_MIN:'+CONVERT(NVARCHAR(30),@RTYPE_NUM_MIN);
PRINT '@RTYPE_NUM_MAX:'+CONVERT(NVARCHAR(30),@RTYPE_NUM_MAX);
SET @RTYPE_NUM_MAX = ISNULL(@RTYPE_NUM_MAX,0);
SET @RTYPE_NUM_MIN = ISNULL(@RTYPE_NUM_MIN,0);
IF @RTYPE_NUM_MIN = @RTYPE_NUM_MAX BEGIN
SET @RTYPE_NUM_MIN = 0
END
--새롭게 지정할 넘버는 가장 작은 값에 + 1을 해준다.
SET @RTYPE_NUM_MIN = @RTYPE_NUM_MIN + 1;
UPDATE RDR 
SET RDR.RTYPE_NUM = @RTYPE_NUM_MIN
FROM   NERP_CONV_SCP_RUN_DT_RANGE RDR WITH(NOLOCK)
WHERE  1=1
AND    RDR.MODULE = @MODULE
AND    RDR.ROLLIN = @ROLLIN
AND    RDR.RTYPE_NUM = @RTYPE_NUM_MAX;
SELECT TOP 1 @V_FR_YYYYMMDD = FR_YYYYMMDD FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE MODULE=@MODULE AND ROLLIN=@ROLLIN ORDER BY RTYPE_NUM DESC;
SELECT TOP 1 @V_TO_YYYYMMDD = TO_YYYYMMDD FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE MODULE=@MODULE AND ROLLIN=@ROLLIN ORDER BY RTYPE_NUM DESC;
--79주차
SELECT TOP 80 @FR_YYYYMMDD = BASIS_YYYYMMDD FROM   dbo.SCM_SYS_CALENDAR_M AS CM WITH(NOLOCK) WHERE CM.DAYOFWEEK = 'MON' AND BASIS_YYYYMMDD <= @V_FR_YYYYMMDD ORDER BY CM.BASIS_YYYYMMDD DESC;
SET @TO_YYYYMMDD = @V_FR_YYYYMMDD;
PRINT '@V_FR_YYYYMMDD:' + @V_FR_YYYYMMDD;
PRINT '@V_TO_YYYYMMDD:' + @V_TO_YYYYMMDD;
PRINT '@FR_YYYYMMDD  :' + @FR_YYYYMMDD  ;
PRINT '@TO_YYYYMMDD  :' + @TO_YYYYMMDD  ;
--주간계산
--@NUM_WEEK
DECLARE @Date1 NVARCHAR(8) = @FR_YYYYMMDD;
DECLARE @Date2 NVARCHAR(8) = @TO_YYYYMMDD;
-- 날짜 차이 계산 후 주차로 변환 (소수점 1자리까지)
SET @NUM_WEEK = FORMAT(ROUND(DATEDIFF(DAY, CONVERT(DATE, @Date1), CONVERT(DATE, @Date2)) / 7.0, 1),'#.0');
SET @RTYPE_DESC = @MODULE+N'_'+@ROLLIN+N'_TO일자_'+SUBSTRING(@FR_YYYYMMDD,3,2)+N'년'+SUBSTRING(@FR_YYYYMMDD,5,2)+N'월'+SUBSTRING(@FR_YYYYMMDD,7,2)+N'일주차_'+@NUM_WEEK+N'주간';
--SET @RTYPE_DESC = @MODULE+N'_'+@ROLLIN+N'_TO일자_'+N'24년01월22일주차_16주간';
PRINT @RTYPE_DESC;
IF @RTYPE_NUM_MAX = 0 BEGIN SET @RTYPE_NUM_MAX = 99999 END;
INSERT INTO NERP_CONV_SCP_RUN_DT_RANGE
(MODULE, ROLLIN, RTYPE_NUM, RTYPE_DESC, FR_YYYYMMDD, TO_YYYYMMDD)  VALUES
(@MODULE,@ROLLIN,@RTYPE_NUM_MAX,@RTYPE_DESC, @FR_YYYYMMDD, @TO_YYYYMMDD)
GO

/* 1. 잡관리 초기화 */
UPDATE dbo.NERP_CONV_JOB_CONTROL
SET RUN_FLAG = 0, LAST_RUNTIME = GETDATE()
WHERE RTYPE =N'SCP' AND CATEGORY_NAME IN( N'NERP_CONV',N'NERP_ETL');

--ROLLIN STAGE BEFORE, ROLLIN STAGE AFTER PRE, ROLLIN STAGE AFTER 3가지로 구분 되어야 한다.
DECLARE @GRNUM INT=0;
DECLARE @GRAPPLY NVARCHAR(10);
DECLARE @GR_BATCH_ID BIGINT;
--아래 값이 3이면 루프 3번 된다.
--잡 처리별(BEFORE,AFTER_PRE,AFTER) 동일 넘버 사용위함
WHILE @GRNUM < 3 BEGIN
    --그룹배치ID생성
    SET @GRNUM = @GRNUM + 1;
    SET @GRAPPLY = (CASE WHEN @GRNUM = 1 THEN 'BEFORE' WHEN @GRNUM = 2 THEN 'AFTER_PRE' WHEN @GRNUM = 3 THEN 'AFTER' END)
    SET @GR_BATCH_ID = NEXT VALUE FOR [dbo].[SEQ1_NERP_CONV_ALL_TABLE];
    --신규 GR_BATCH_ID 입력
    INSERT INTO [dbo].[NERP_CONV_JOB_BATCH]([RTYPE],[GR_BATCH_ID],[GR_BATCH_APPLY],[CREATION_DATE])
    VALUES('SCP',@GR_BATCH_ID,@GRAPPLY,GETDATE());
END;

/* 1. 그룹 개수 지정 */
DECLARE @GroupCount INT = 4;  -- 원하는 그룹 개수 (예: 2, 4, 5)

/* 2. 그룹 상태 테이블 준비 */
DECLARE @Groups TABLE
(
    GroupNo INT PRIMARY KEY,
    TotalMinutes INT
);

DECLARE @i INT = 1;
WHILE @i <= @GroupCount
BEGIN
    INSERT INTO @Groups (GroupNo, TotalMinutes) VALUES (@i, 0);
    SET @i += 1;
END

/* 3. 기존 그룹 정보 초기화 */
UPDATE dbo.NERP_CONV_CUTOFF_TAKES_MIN
SET GROUP_NUM = NULL,
    GROUP_COUNT = @GroupCount
WHERE RTYPE =N'SCP';

/* 4. Greedy 방식 분배 */
DECLARE @TableName NVARCHAR(128), @Minutes INT, @TargetGroup INT;

DECLARE cur CURSOR FOR
    SELECT TABLE_NAME, AVG
    FROM dbo.NERP_CONV_CUTOFF_TAKES_MIN
    WHERE RTYPE =N'SCP'
    ORDER BY AVG DESC;   -- 소요시간 큰 것부터 배정

OPEN cur;
FETCH NEXT FROM cur INTO @TableName, @Minutes;

WHILE @@FETCH_STATUS = 0
BEGIN
    -- 현재 합계가 가장 작은 그룹 선택
    SELECT TOP 1 @TargetGroup = GroupNo
    FROM @Groups
    ORDER BY TotalMinutes ASC;

    -- 해당 테이블에 그룹번호 업데이트
    UPDATE dbo.NERP_CONV_CUTOFF_TAKES_MIN
    SET GROUP_NUM = @TargetGroup,
        GROUP_COUNT = @GroupCount,
        LAST_UPDATE_DATE = GETDATE()
    WHERE RTYPE =N'SCP' AND TABLE_NAME = @TableName;

    -- 그룹 합계 갱신
    UPDATE @Groups
    SET TotalMinutes = TotalMinutes + @Minutes
    WHERE GroupNo = @TargetGroup;

    FETCH NEXT FROM cur INTO @TableName, @Minutes;
END

CLOSE cur;
DEALLOCATE cur;

