SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @cnt INT;

BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE SCM_FACTORY_M
       SET MES_SOURCE_GROUP = 'PMSE'
         , UPDATE_TIME      = GETDATE()
     WHERE FACTORY_ID IN ('ED');

    SET @cnt = @@ROWCOUNT;

    COMMIT TRANSACTION;

    PRINT N'[OK] SCM_FACTORY_M updated. rows = ' + CAST(@cnt AS NVARCHAR(10));
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

    DECLARE @msg NVARCHAR(2048) = N'[FAIL] ' + ERROR_MESSAGE()
                                + N' (Msg ' + CAST(ERROR_NUMBER() AS NVARCHAR(10))
                                + N', Line ' + CAST(ERROR_LINE() AS NVARCHAR(10)) + N')';
    RAISERROR(@msg, 16, 1);
END CATCH

