USE [LGCE_SCMDEV]
GO
declare @v_program_name nvarchar(150);
select top 1 @v_program_name = program_name
from SCM_SYS_LOG_BATCH with (nolock)
where 1 =1 
and program_name in ( 'FN_ERP_NPP0220_TransferPosting_PRG','PR_SCP_PLN_MRP_PROD_TARGET_NERP')
AND CREATION_DATE >= DATEADD(hour, -1, GETDATE())
order by creation_date desc;
PRINT @v_program_name;

IF(@v_program_name IS NULL)
	BEGIN
        --PRINT 'send message'
		EXEC SCM_ADM_SMS_SEND_BATCH 104, '';
	END
GO

