USE [LGCE_SCMDEV]
GO
    DECLARE		@v_curr_date	        DATETIME	= GETDATE();
    DECLARE		@v_this_monday	        VARCHAR(8)	= '';

    SELECT @v_this_monday    = FORMAT(DATEADD(DD, 2 - DATEPART(DW, DATEADD(DD, -1, @v_curr_date)), DATEADD(DD, -1, @v_curr_date)), 'yyyyMMdd')

    EXEC dbo.PR_SCP_RPT_ELEC_PSI_FOR_IF '81_HM', 'EE_HM', @v_this_monday, 'FN';
    EXEC dbo.PR_SCP_RPT_ELEC_PSI_FOR_IF '81_ST', 'EE_ST', @v_this_monday, 'FN';
    EXEC dbo.PR_SCP_RPT_ELEC_PSI_FOR_IF '81_UC', 'EE_UC', @v_this_monday, 'FN';
    EXEC dbo.PR_SCP_RPT_ELEC_PSI_FOR_IF '81_HD', 'EE_HD', @v_this_monday, 'FN';

GO

