DECLARE @MODELING_ID NVARCHAR(128);
DECLARE @DPLAN_TYPE NVARCHAR(128);
DECLARE @return_value   INT
DECLARE @v_modeling_id NVARCHAR(1000)='X';
DECLARE @v_ERROR_modeling_id NVARCHAR(1000)='';
DECLARE @v_division_id NVARCHAR(1000);
DECLARE @v_revision_no NVARCHAR(1000);
DECLARE @v_confirm_user NVARCHAR(1000)='test_user';
DECLARE @ERROR_modeling_id TABLE(modeling_id INT PRIMARY KEY);
DECLARE @SQL NVARCHAR(MAX);

DELETE @ERROR_modeling_id;
DECLARE cur CURSOR FAST_FORWARD READ_ONLY LOCAL FOR
    WITH W_RAW AS (
        --SELECT TRIM('1 ') AS MODELING_ID, 04 AS SORT_SEQ,TRIM('40   ') AS DIVISION_ID, TRIM('PR,MA,/*SE,*/FN') AS PLAN_TYPE UNION
        SELECT TRIM('1 ') AS MODELING_ID, 04 AS SORT_SEQ,TRIM('40   ') AS DIVISION_ID, TRIM('PR,MA,FN') AS PLAN_TYPE UNION
        SELECT TRIM('2 ') AS MODELING_ID, 03 AS SORT_SEQ,TRIM('81   ') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('3 ') AS MODELING_ID, 12 AS SORT_SEQ,TRIM('82   ') AS DIVISION_ID, TRIM('PR,MA,SE,FN') AS PLAN_TYPE UNION
        SELECT TRIM('4 ') AS MODELING_ID, 01 AS SORT_SEQ,TRIM('EE   ') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('5 ') AS MODELING_ID, 05 AS SORT_SEQ,TRIM('81_UC') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('6 ') AS MODELING_ID, 06 AS SORT_SEQ,TRIM('EE_UC') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('7 ') AS MODELING_ID, 07 AS SORT_SEQ,TRIM('81_HM') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('8 ') AS MODELING_ID, 08 AS SORT_SEQ,TRIM('EE_HM') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('9 ') AS MODELING_ID, 02 AS SORT_SEQ,TRIM('81_ST') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('10') AS MODELING_ID, 09 AS SORT_SEQ,TRIM('EE_ST') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('11') AS MODELING_ID, 10 AS SORT_SEQ,TRIM('81_HD') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('12') AS MODELING_ID, 11 AS SORT_SEQ,TRIM('EE_HD') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE 
    )
    SELECT WR.MODELING_ID
          --,WR.DIVISION_ID
          --,WR.PLAN_TYPE
          ,CA.token AS DPLAN_TYPE
    FROM W_RAW AS WR
    CROSS APPLY STRING_SPLIT(WR.PLAN_TYPE,',') AS CA
    WHERE 1=1
    --AND MODELING_ID <> 4
    --AND MODELING_ID <> 9
    --AND MODELING_ID <> 1
    --AND MODELING_ID = 12
    AND MODELING_ID  IN (1,2)
    AND (WR.MODELING_ID = '1' AND CA.token='FN')
    --AND MODELING_ID  IN (9,10,11,12)
    --AND CA.token<>'PR'
    --AND NOT (WR.MODELING_ID = '9' AND CA.token='MA')
    --AND NOT (WR.MODELING_ID = '4' AND CA.token='MA')
    --AND CA.token<>'PR'
    --AND (
    --     (WR.MODELING_ID = '5' AND CA.token='FN')
    --  OR (WR.MODELING_ID = '7' AND CA.token='MA')
    --  OR (WR.MODELING_ID = '7' AND CA.token='FN')
    --  OR (WR.MODELING_ID = '8' AND CA.token='PR')
    --  OR (WR.MODELING_ID = '8' AND CA.token='MA')
    --  OR (WR.MODELING_ID = '8' AND CA.token='FN')
    --  )
    ORDER BY CASE WHEN CA.token='PR' THEN 1 WHEN CA.token='MA' THEN 2 WHEN CA.token='SE' THEN 3 ELSE 4 END, SORT_SEQ;

OPEN cur

FETCH NEXT FROM cur INTO @MODELING_ID, @DPLAN_TYPE

WHILE @@FETCH_STATUS = 0 BEGIN

    --SET @SQL = N'
    --    PR_SCP_ENG_CONTROL '''+@MODELING_ID+''', '''+@DPLAN_TYPE +''';';

    IF EXISTS ( SELECT 1 FROM @ERROR_modeling_id WHERE modeling_id = CONVERT(INT,@MODELING_ID) ) 
    BEGIN
        -- CONTINUE 전에 다음 FETCH를 명시적으로 호출
        FETCH NEXT FROM cur INTO @MODELING_ID, @DPLAN_TYPE;
        CONTINUE;
    END;


    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'1 @MODELING_ID:'+CONVERT(NVARCHAR(MAX),@MODELING_ID) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'1 @v_ERROR_modeling_id:'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'1 @DPLAN_TYPE:'+CONVERT(NVARCHAR(MAX),@DPLAN_TYPE) );

    SET @SQL = N'
        DECLARE @return_value   INT
        EXEC @return_value = [dbo].[PR_SCP_ENG_CONTROL] '''+@MODELING_ID+N''', '''+@DPLAN_TYPE +N''';
        --SELECT ''Return Value'' = @return_value
        SELECT @ret_val = @return_value';

    PRINT @SQL;
    EXEC sys.sp_executesql @SQL, N'@ret_val INT OUTPUT', @ret_val=@return_value OUTPUT;
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'2 @return_value:'+CONVERT(NVARCHAR(MAX),@return_value) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'2 @MODELING_ID:'+CONVERT(NVARCHAR(MAX),@MODELING_ID) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'2 @v_ERROR_modeling_id:'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'2 @DPLAN_TYPE:'+CONVERT(NVARCHAR(MAX),@DPLAN_TYPE) );
    PRINT '@return_value :'+CONVERT(NVARCHAR(MAX),@return_value);
    PRINT '@v_ERROR_modeling_id :'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id);

    IF @DPLAN_TYPE = 'PR' AND @return_value  > -1
    BEGIN

    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'3 @return_value:'+CONVERT(NVARCHAR(MAX),@return_value) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'3 @MODELING_ID:'+CONVERT(NVARCHAR(MAX),@MODELING_ID) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'3 @v_ERROR_modeling_id:'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'3 @DPLAN_TYPE:'+CONVERT(NVARCHAR(MAX),@DPLAN_TYPE) );

        SELECT TOP 1 @v_modeling_id = modeling_id
              ,@v_division_id = smp.division_id
              ,@v_revision_no = smp.PLAN_NAME+'-'+plan_type+'-'+convert(nvarchar(30),plan_seq) --AS revision_no
        --SELECT TOP 1 modeling_id,smp.division_id,smp.PLAN_NAME+'-'+plan_type+'-'+convert(nvarchar(30),plan_seq) AS revision_no,confirm_user,*
        FROM   dbo.scm_mst_plan smp  WITH(NOLOCK)
        INNER JOIN scm_mst_plan_detail mpd  WITH(NOLOCK)
        ON    smp.division_id=mpd.division_id
        AND   smp.plan_id    =mpd.plan_id
        AND   mpd.PLAN_STATUS = '1'
        AND   mpd.PLAN_TYPE = 'PR'
        AND   isnull(mpd.CONFIRM_USER,'') = ''
        AND   modeling_id = @MODELING_ID--'4'--@p_modeling_id
        ORDER BY mpd.LAST_UPDATE_DATE DESC
        ;
        --print @v_modeling_id;
        --print @v_division_id;
        --print @v_revision_no;
        --print @v_confirm_user;
        SET @SQL = N'
        EXEC SCP0015_SAVE_PLAN_MST_COMFIRM @p_modeling_id='''+@v_modeling_id+''',@p_division_id='''+@v_division_id+''',@p_revision_no='''+@v_revision_no+''',@p_confirm_user='''+@v_confirm_user+''';';
        EXEC sys.sp_executesql @SQL;
    END;

    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'4 @return_value:'+CONVERT(NVARCHAR(MAX),@return_value) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'4 @MODELING_ID:'+CONVERT(NVARCHAR(MAX),@MODELING_ID) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'4 @v_ERROR_modeling_id:'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'4 @DPLAN_TYPE:'+CONVERT(NVARCHAR(MAX),@DPLAN_TYPE) );

    IF @return_value = -1
    BEGIN 
        INSERT INTO @ERROR_modeling_id(modeling_id)
        VALUES(CONVERT(INT,@MODELING_ID));
    END;

    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'5 @return_value:'+CONVERT(NVARCHAR(MAX),@return_value) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'5 @MODELING_ID:'+CONVERT(NVARCHAR(MAX),@MODELING_ID) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'5 @v_ERROR_modeling_id:'+CONVERT(NVARCHAR(MAX),@v_ERROR_modeling_id) );
    INSERT DROP_PLOG(PGM_NM,MSG)VALUES('Sql Agent : PR_SCP_ENG_CONTROL',N'5 @DPLAN_TYPE:'+CONVERT(NVARCHAR(MAX),@DPLAN_TYPE) );

    FETCH NEXT FROM cur INTO @MODELING_ID, @DPLAN_TYPE

END

CLOSE cur
DEALLOCATE cur

DECLARE @MODELING_ID NVARCHAR(128);
DECLARE @DPLAN_TYPE NVARCHAR(128);
DECLARE @v_modeling_id NVARCHAR(1000);
DECLARE @v_division_id NVARCHAR(1000);
DECLARE @v_revision_no NVARCHAR(1000);
DECLARE @v_confirm_user NVARCHAR(1000)='test_user';
DECLARE @SQL NVARCHAR(MAX);

DECLARE cur CURSOR FAST_FORWARD READ_ONLY LOCAL FOR
    WITH W_RAW AS (
        SELECT TRIM('1 ') AS MODELING_ID, 05 AS SORT_SEQ,TRIM('40   ') AS DIVISION_ID, TRIM('PR,MA,SE,FN') AS PLAN_TYPE UNION
        SELECT TRIM('2 ') AS MODELING_ID, 04 AS SORT_SEQ,TRIM('81   ') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('3 ') AS MODELING_ID, 12 AS SORT_SEQ,TRIM('82   ') AS DIVISION_ID, TRIM('PR,MA,SE,FN') AS PLAN_TYPE UNION
        SELECT TRIM('4 ') AS MODELING_ID, 01 AS SORT_SEQ,TRIM('EE   ') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('5 ') AS MODELING_ID, 06 AS SORT_SEQ,TRIM('81_UC') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('6 ') AS MODELING_ID, 07 AS SORT_SEQ,TRIM('EE_UC') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('7 ') AS MODELING_ID, 08 AS SORT_SEQ,TRIM('81_HM') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('8 ') AS MODELING_ID, 09 AS SORT_SEQ,TRIM('EE_HM') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('9 ') AS MODELING_ID, 03 AS SORT_SEQ,TRIM('81_ST') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('10') AS MODELING_ID, 10 AS SORT_SEQ,TRIM('EE_ST') AS DIVISION_ID, TRIM('PR,MA,FN   ') AS PLAN_TYPE UNION
        SELECT TRIM('11') AS MODELING_ID, 11 AS SORT_SEQ,TRIM('81_HD') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE UNION
        SELECT TRIM('12') AS MODELING_ID, 02 AS SORT_SEQ,TRIM('EE_HD') AS DIVISION_ID, TRIM('PR,FN      ') AS PLAN_TYPE
    )
    SELECT WR.MODELING_ID
          --,WR.DIVISION_ID
          --,WR.PLAN_TYPE
          ,CA.token AS DPLAN_TYPE
    FROM W_RAW AS WR
    CROSS APPLY STRING_SPLIT(WR.PLAN_TYPE,',') AS CA
    WHERE 1=1
    AND   CA.token = 'PR'
    ORDER BY SORT_SEQ;

OPEN cur

FETCH NEXT FROM cur INTO @MODELING_ID, @DPLAN_TYPE

WHILE @@FETCH_STATUS = 0 BEGIN

    SET @SQL = N'
        PR_SCP_ENG_CONTROL '''+@MODELING_ID+''', '''+@DPLAN_TYPE +''';';
    PRINT @SQL;
    EXEC sys.sp_executesql @SQL;
    IF @DPLAN_TYPE = 'PR' 
    BEGIN
        SELECT TOP 1 @v_modeling_id = modeling_id
              ,@v_division_id = smp.division_id
              ,@v_revision_no = smp.PLAN_NAME+'-'+plan_type+'-'+convert(nvarchar(30),plan_seq) --AS revision_no
        --SELECT TOP 1 modeling_id,smp.division_id,smp.PLAN_NAME+'-'+plan_type+'-'+convert(nvarchar(30),plan_seq) AS revision_no,confirm_user,*
        FROM   dbo.scm_mst_plan smp  WITH(NOLOCK)
        INNER JOIN scm_mst_plan_detail mpd  WITH(NOLOCK)
        ON    smp.division_id=mpd.division_id
        AND   smp.plan_id    =mpd.plan_id
        AND   mpd.PLAN_STATUS = '1'
        AND   mpd.PLAN_TYPE = 'PR'
        AND   isnull(mpd.CONFIRM_USER,'') = ''
        AND   modeling_id = @MODELING_ID--'4'--@p_modeling_id
        ORDER BY mpd.LAST_UPDATE_DATE DESC
        ;
        --print @v_modeling_id;
        --print @v_division_id;
        --print @v_revision_no;
        --print @v_confirm_user;
        SET @SQL = N'
        EXEC SCP0015_SAVE_PLAN_MST_COMFIRM @p_modeling_id='''+@v_modeling_id+''',@p_division_id='''+@v_division_id+''',@p_revision_no='''+@v_revision_no+''',@p_confirm_user='''+@v_confirm_user+''';';
        EXEC sys.sp_executesql @SQL;

    END;

    FETCH NEXT FROM cur INTO @MODELING_ID, @DPLAN_TYPE

END

CLOSE cur
DEALLOCATE cur

USE [LGCE_SCMDEV]
GO
DECLARE @return_value    INT
DECLARE @p_plan_name     NVARCHAR(8)   = CONVERT(CHAR(8), GETDATE(), 112)
DECLARE @p_division_id   NVARCHAR(30);

DECLARE CUR_DIVISION CURSOR FOR
	SELECT DIVISION_ID FROM SCM_MST_DIVISION PG WITH(NOLOCK)
	WHERE  ATTRIBUTE4 = 'UC';

OPEN CUR_DIVISION;
FETCH NEXT FROM CUR_DIVISION INTO @p_division_id;

WHILE (@@FETCH_STATUS = 0)
	BEGIN
	    EXEC @return_value = [dbo].[PR_SCP_OPMZ_PLAN_CTRL_ACTV_M] @P_PLAN_START_YYYYMMDD = @p_plan_name
                                                         ,@P_DIVISION_ID		 = @p_division_id
                                                         ,@P_OPMZ_PRS_ID		 = NULL
                                                         ,@P_OPMZ_PLAN_GR_ID	 = NULL;

        SELECT 'Return Value' = @return_value;

		FETCH NEXT FROM CUR_DIVISION INTO @p_division_id;
	END

CLOSE CUR_DIVISION;
DEALLOCATE CUR_DIVISION;

DECLARE @GroupID        nvarchar(50);
DECLARE @ProcedureName  nvarchar(200);
DECLARE @Param1         nvarchar(50);
DECLARE @Param2         nvarchar(50);
DECLARE @Sql            NVARCHAR(MAX);

-- 1. 조건에 맞는 대상 1건 조회 (M.VALID = 'Y', M.IMMEDIATE_FLAG = 'Y')
SELECT TOP 1 
    @GroupID       = M.GROUP_ID,
    @ProcedureName = D.JOB_ID,       
    @Param1        = D.PARAMETER1,
    @Param2        = D.PARAMETER2
--SELECT M.GROUP_ID, D.JOB_ID,D.PARAMETER1, D.PARAMETER2
FROM JOB_SCHEDULE_MASTER M
INNER JOIN JOB_SCHEDULE_DETAIL D 
    ON M.GROUP_ID = D.GROUP_ID
WHERE M.VALID = 'Y'                          
  AND M.GROUP_ID LIKE 'ENGINE_RUN_UI%'
  AND M.IMMEDIATE_FLAG = 'Y'   
ORDER BY M.GROUP_ID;                  


print   @GroupID +CHAR(10)+    @ProcedureName+CHAR(10)+@Param1 +CHAR(10)+ @Param2  

-- 2. 실행할 대상이 존재하는 경우 처리
IF @GroupID IS NOT NULL
BEGIN

    -- 2-1. LATEST_RUN_DATE를 현재 시간(GETDATE())으로 업데이트
    UPDATE JOB_SCHEDULE_MASTER
    SET LATEST_RUN_DATE = GETDATE()
      , IMMEDIATE_FLAG = 'N'  -- 2-3. 성공/실패 여부와 관계없이 IMMEDIATE_FLAG를 'N'으로 변경
    WHERE GROUP_ID = @GroupID;

    UPDATE JOB_SCHEDULE_DETAIL
    SET START_DATE = GETDATE(),
        END_DATE   = NULL
    WHERE GROUP_ID = @GroupID;

    -- 2-2. 프로시저 실행 및 오류 처리 (TRY...CATCH)
    BEGIN TRY
        SET @Sql = N'EXEC ' + QUOTENAME(@ProcedureName) + N' @P1, @P2';

        PRINT '**Start: ' + @ProcedureName;
        --select @Sql , @Param1 ,@Param2

        EXEC sp_executesql 
            @stmt   = @Sql, 
            @params = N'@P1 NVARCHAR(50), @P2 NVARCHAR(50)', 
            @P1     = @Param1, 
            @P2     = @Param2;

        PRINT '**success: ' + @ProcedureName;
    END TRY
    BEGIN CATCH
        -- 프로시저 실행 중 오류 발생 시 에러 출력 (필요 시 별도 로그 테이블에 저장 가능)
        PRINT '**Error [' + @ProcedureName + ']: ' + ERROR_MESSAGE();
    END CATCH


    UPDATE A
    SET END_DATE = GETDATE(), STATUS ='END'
    FROM JOB_SCHEDULE_DETAIL A
    WHERE GROUP_ID = @GroupID;


    INSERT INTO JOB_SCHEDULE_HISTORY
    SELECT [GROUP_ID], [DIVISION_ID], [JOB_ID], [JOB_DESC], [NO], [SEQ], [STATUS], [ERROR_MSG], [START_DATE], [END_DATE], 'SYSTEM' [CREATE_USER_ID], GETDATE() [CREATE_DATE], NULL [MODIFY_USER_ID], NULL [MODIFY_DATE]
    FROM JOB_SCHEDULE_DETAIL WITH(NOLOCK)
     WHERE GROUP_ID = @GroupID




END
